async def act(page):
    """
    From the current New Product form state, fill required fields for the product and save:
      - Name: Energy-Bulk Man Yoga Pant
      - Price: 69.99
      - Qty: 50
      - Stock Availability: In Stock
      - Size: 38
      - Color: Yellow

    The Save click is the final action and may navigate away.
    """
    # ensure the page is idle before interacting
    await page.wait_for_load_state("networkidle")

    # --- Knowledge base functions ---
    # There are no functions provided in the knowledge_base for this task, so none are used.

    # 1) Ensure General section is active so Name, Size and Color controls are available
    try:
        general = page.get_by_role("link", name="General")
        if await general.count() > 0:
            await general.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        pass

    # 2) Fill Product Name (use explicit table->rowgroup->row path if present)
    try:
        # try to scope via table row that contains 'name'
        name_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name=lambda n: n and "name" in n.lower()
        )
        if await name_row.count() > 0:
            name_tb = name_row.get_by_role("textbox", name=lambda n: n and "name" in n.lower())
            if await name_tb.count() > 0:
                await name_tb.fill("Energy-Bulk Man Yoga Pant")
        else:
            # fallback: any textbox whose accessible name contains 'name'
            tb = page.get_by_role("textbox", name=lambda n: n and "name" in n.lower())
            if await tb.count() > 0:
                await tb.fill("Energy-Bulk Man Yoga Pant")
    except Exception:
        # final fallback attempt
        try:
            tb2 = page.get_by_role("textbox", name=lambda n: n and "product name" in n.lower())
            if await tb2.count() > 0:
                await tb2.fill("Energy-Bulk Man Yoga Pant")
        except Exception:
            pass

    # 3) Click Prices to reveal price control and fill Price = 69.99
    try:
        prices = page.get_by_role("link", name="Prices")
        if await prices.count() > 0:
            await prices.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        pass

    try:
        # prefer an explicit price textbox if present under a table row
        price_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name=lambda n: n and "price" in n.lower()
        )
        if await price_row.count() > 0:
            price_tb = price_row.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await price_tb.count() > 0:
                await price_tb.fill("69.99")
        else:
            # fallback to any textbox with 'price' in its accessible name
            any_price = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await any_price.count() > 0:
                await any_price.fill("69.99")
    except Exception:
        pass

    # 4) Inventory: set Qty = 50 and Stock Availability = In Stock
    try:
        # Inventory controls are inside the Inventory group in the accessibility tree
        inv_group = page.get_by_role("group", name="Inventory")
        if await inv_group.count() > 0:
            # Qty textbox
            try:
                qty_row = inv_group.get_by_role("table").get_by_role("rowgroup").get_by_role(
                    "row", name=lambda n: n and "qty" in n.lower()
                )
                if await qty_row.count() > 0:
                    qty_tb = qty_row.get_by_role("textbox", name=lambda n: n and "qty" in n.lower())
                    if await qty_tb.count() > 0:
                        await qty_tb.fill("50")
                else:
                    # fallback: any textbox inside Inventory group with 'qty' or 'quantity' in name
                    qty_tb2 = inv_group.get_by_role("textbox", name=lambda n: n and ("qty" in n.lower() or "quantity" in n.lower()))
                    if await qty_tb2.count() > 0:
                        await qty_tb2.fill("50")
            except Exception:
                pass

            # Stock Availability combobox
            try:
                stock_cb = inv_group.get_by_role("combobox", name=lambda n: n and "stock availability" in n.lower())
                if await stock_cb.count() == 0:
                    # fallback: any combobox in inventory group whose name contains 'stock' or 'availability'
                    stock_cb = inv_group.get_by_role("combobox", name=lambda n: n and ("stock" in n.lower() or "availability" in n.lower()))

                if await stock_cb.count() > 0:
                    # select by visible label
                    await stock_cb.select_option({"label": "In Stock"})
            except Exception:
                pass
    except Exception:
        # fallback if Inventory group not found, attempt global selectors
        try:
            qty_tb = page.get_by_role("textbox", name=lambda n: n and ("qty" in n.lower() or "quantity" in n.lower()))
            if await qty_tb.count() > 0:
                await qty_tb.fill("50")
        except Exception:
            pass
        try:
            stock_cb = page.get_by_role("combobox", name=lambda n: n and ("stock" in n.lower() or "availability" in n.lower()))
            if await stock_cb.count() > 0:
                await stock_cb.select_option({"label": "In Stock"})
        except Exception:
            pass

    # 5) Set Size -> 38 and Color -> Yellow (most likely under General)
    try:
        # Size combobox
        size_cb = page.get_by_role("combobox", name=lambda n: n and "size" in n.lower())
        if await size_cb.count() > 0:
            await size_cb.select_option({"label": "38"})
    except Exception:
        pass

    try:
        # Color combobox
        color_cb = page.get_by_role("combobox", name=lambda n: n and "color" in n.lower())
        if await color_cb.count() > 0:
            # try label variants
            for label in ["Yellow", "yellow"]:
                try:
                    await color_cb.select_option({"label": label})
                    break
                except Exception:
                    continue
    except Exception:
        pass

    # 6) Final action: click Save (navigation-causing). Scope Save under document as recommended.
    save_clicked = False
    try:
        doc = page.get_by_role("document")
        if await doc.count() > 0:
            save_btn = doc.get_by_role("button", name="Save")
            if await save_btn.count() > 0:
                await save_btn.click()
                save_clicked = True
    except Exception:
        pass

    if not save_clicked:
        # fallback: any Save button on the page
        try:
            any_save = page.get_by_role("button", name="Save")
            if await any_save.count() > 0:
                await any_save.click()
                save_clicked = True
        except Exception:
            pass

    if not save_clicked:
        raise RuntimeError("Unable to find Save button to complete product creation")
